{
  "passageId": "corporate-law",
  "itemKey": "b",
  "form": "BOGI",
  "situation": {
    "description": "주식회사가 자본 잉여금 일부로 무상 증자를 실시할 때 추가 발행 주식 수와 증자 전후 자본금 및 그 증가율을 계산하는 상황이다.",
    "slotRef": null,
    "bogiText": "주식회사 가람의 발행된 총 주식 수는 12,000주이며, 모든 주식의 액면가는 5,000원이다. 가람은 자본 잉여금 4,000만 원 중 1,500만 원을 사용하여 무상 증자를 실시하기로 했다. 추가 발행하는 주식의 액면가도 5,000원이며, 이 주식은 모두 기존 주주들에게 무상으로 분배한다. 이 무상 증자 외에 주식 수나 액면가를 바꾸는 일은 없다."
  },
  "usedRuleIds": [
    "R3",
    "R6"
  ],
  "steps": [
    {
      "n": 1,
      "given": "무상 증자 전 발행된 총 주식 수는 12,000주이고, 주식의 액면가는 5,000원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "무상 증자 전 자본금은 12,000주 × 5,000원 = 6,000만 원이다."
    },
    {
      "n": 2,
      "given": "무상 증자에 사용하는 자본 잉여금은 1,500만 원이고, 추가 발행 주식의 액면가는 5,000원이다.",
      "ruleId": "R6",
      "ruleQuote": "주식회사는 무상 증자를 실시하여 자본 잉여금이나 이익 잉여금의 일부 혹은 전부에 해당하는 만큼의 주식을 추가로 발행하여 주주들에게 무상으로 분배한다.",
      "result": "추가 발행하여 무상으로 분배하는 주식 수는 1,500만 원 ÷ 5,000원 = 3,000주이다."
    },
    {
      "n": 3,
      "given": "기존 주식은 12,000주이고, 2단계에서 구한 추가 발행 주식은 3,000주이며, 모든 주식의 액면가는 5,000원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "무상 증자 후 발행된 총 주식 수는 15,000주이고, 자본금은 15,000주 × 5,000원 = 7,500만 원이다."
    },
    {
      "n": 4,
      "given": "1단계의 증자 전 자본금은 6,000만 원이고, 3단계의 증자 후 자본금은 7,500만 원이다.",
      "ruleId": "R3",
      "ruleQuote": "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
      "result": "자본금 증가액은 7,500만 원 - 6,000만 원 = 1,500만 원이고, 증자 전 대비 자본금 증가율은 1,500만 원 ÷ 6,000만 원 × 100 = 25%이다."
    }
  ],
  "derivedFacts": [
    {
      "id": "F1",
      "text": "가람의 무상 증자 전 자본금은 6,000만 원이다.",
      "fromSteps": [
        1
      ],
      "ifDifferent": "기존 주식 수가 10,000주이고 액면가는 같았다면, 무상 증자 전 자본금은 5,000만 원이 된다."
    },
    {
      "id": "F2",
      "text": "가람이 이번 무상 증자로 주주들에게 무상 분배하는 주식은 총 3,000주이다.",
      "fromSteps": [
        2
      ],
      "ifDifferent": "무상 증자에 사용하는 금액이 1,000만 원이고 액면가는 같았다면, 무상 분배하는 주식은 총 2,000주가 된다."
    },
    {
      "id": "F3",
      "text": "가람의 무상 증자 후 자본금은 7,500만 원이다.",
      "fromSteps": [
        2,
        3
      ],
      "ifDifferent": "무상 증자에 사용하는 금액이 2,000만 원이고 나머지 조건은 같았다면, 증자 후 총 주식 수는 16,000주이고 자본금은 8,000만 원이 된다."
    },
    {
      "id": "F4",
      "text": "이번 무상 증자로 가람의 자본금은 증자 전보다 25% 증가한다.",
      "fromSteps": [
        1,
        3,
        4
      ],
      "ifDifferent": "기존 주식 수가 15,000주이고 나머지 조건은 같았다면, 증자 전 자본금은 7,500만 원이므로 자본금 증가율은 20%가 된다."
    }
  ],
  "selfCheck": "무상 증자에 쓰는 1,500만 원은 보유 자본 잉여금 4,000만 원을 넘지 않으며, 추가 주식 수와 증자 전후 자본금은 제시된 금액·주식 수·액면가 및 R3·R6에서 바로 산출된다. 자본금 증가율은 앞 단계에서 구한 자본금의 차이를 증자 전 자본금으로 나눈 값이며, 모든 반사실 조건도 같은 방식으로 재계산했다."
}

